package com.tuap.backend.auth;
import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tuap.backend.dominio.entidades.AuthIdentity; import com.tuap.backend.persistencia.AuthIdentityDAO;
@Service public class AuthIdentityService { private final AuthIdentityDAO identities; private final IdentityResolver users; private final Clock clock; @org.springframework.beans.factory.annotation.Autowired public AuthIdentityService(AuthIdentityDAO d,IdentityResolver r){this(d,r,Clock.systemUTC());} AuthIdentityService(AuthIdentityDAO d,IdentityResolver r,Clock c){identities=d;users=r;clock=c;}
 public Optional<AuthenticatedUser> findExternalIdentity(AuthProvider p,String subject){return identities.findByProviderAndProviderSubject(p,subject).filter(AuthIdentity::isActive).flatMap(i->users.findByIdAndRole(i.getUserId(),i.getRole()));}
 public List<AuthIdentityResponse> listIdentities(AuthenticatedUser u){return identities.findByUserIdAndRoleAndActiveTrue(u.userId(),u.role()).stream().map(AuthIdentityResponse::from).toList();}
 @Transactional public void ensureLocalIdentity(AuthenticatedUser u){if(!identities.existsByUserIdAndRoleAndProviderAndActiveTrue(u.userId(),u.role(),AuthProvider.LOCAL)) identities.findByProviderAndProviderSubject(AuthProvider.LOCAL,u.userId().toString()).ifPresentOrElse(i->{if(!i.isActive())throw new AuthIdentityConflictException();},()->identities.save(new AuthIdentity(u.userId(),u.role(),AuthProvider.LOCAL,u.userId().toString(),null,clock.instant())));}
 @Transactional public AuthIdentity linkIdentity(AuthenticatedUser u,AuthProvider p,String subject,String email){if(p==null||p==AuthProvider.LOCAL||subject==null||subject.isBlank())throw new AuthIdentityConflictException();return identities.findByProviderAndProviderSubject(p,subject.trim()).map(i->{if(!i.isActive()||!i.getUserId().equals(u.userId())||i.getRole()!=u.role())throw new AuthIdentityConflictException();return i;}).orElseGet(()->identities.save(new AuthIdentity(u.userId(),u.role(),p,subject.trim(),email,clock.instant())));}
 @Transactional public void deactivateIdentity(AuthenticatedUser u,AuthProvider p){AuthIdentity i=identities.findByUserIdAndRoleAndActiveTrue(u.userId(),u.role()).stream().filter(x->x.getProvider()==p).findFirst().orElseThrow(AuthIdentityConflictException::new);if(identities.countByUserIdAndRoleAndActiveTrue(u.userId(),u.role())<=1)throw new LastAuthIdentityException();i.deactivate();identities.save(i);}
 @Transactional public void deactivateAll(AuthenticatedUser u){identities.findByUserIdAndRoleAndActiveTrue(u.userId(),u.role()).forEach(i->{i.deactivate();identities.save(i);});} @Transactional public void updateLastUsed(AuthenticatedUser u,AuthProvider p){identities.findByProviderAndProviderSubject(p,p==AuthProvider.LOCAL?u.userId().toString():"").filter(AuthIdentity::isActive).ifPresent(i->{i.usedAt(clock.instant());identities.save(i);});}}
